#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "bicg.h"

void init_array(int m, int n, double A[42][38], double r[42], double p[38]) {
    int i, j;

    for (i = 0; i < m; i++)
        p[i] = (double)(i % m) / m;
    for (i = 0; i < n; i++) {
        r[i] = (double)(i % n) / n;
        for (j = 0; j < m; j++)
            A[i][j] = (double)(i * (j + 1) % n) / n;
    }
}

